"use strict";

(function () {
  const DEFAULT_TITLE =
    "LÍNEA 3 / RECETA DE APERTURA DE VÁLVULAS";

  const DEFAULT_SUBTITLE =
    "Configuración de la apertura por defecto de las válvulas durante el arranque";

  const LEFT_LABELS = [
    "Cuba de Lavado 1",
    "Cuba de Lavado 2",
    "Cuba de Lavado 3",
    "Cuba de Lavado 4",
    "Cuba de Lavado 5",
    "Cuba de Lavado 6",
    "Cuba de Lavado 7",
    "Cuba de Lavado 8",
    "Cuba de Lavado 9",
    "Cuba de Lavado 10",
    "Cuba de Lavado 11",
    "Cuba de Lavado 12",
    "Cuba de Lavado 13",
    "Cuba de Lavado 14",
    "Tanque Dosificador",
    "Tanque de Mezcla"
  ];

  const RIGHT_LABELS = [
    "Pre-Estiramiento",
    "Entrada Estiramiento",
    "Salida Estiramiento",
    "Preparación",
    "Calef. Rizadoras",
    "Cajas Rizadoras",
    "Agua a Cubas",
    "Secador Zona 1",
    "Secador Zona 2",
    "Secador Zona 3",
    "Secador Zona 4",
    "Secador Zona 5"
  ];

  let latestWidget = null;
  let headerObserver = null;

  function make(tag, className, parent, text) {
    const element = document.createElement(tag);
    element.className = className;

    if (text !== undefined) {
      element.textContent = text;
    }

    parent.appendChild(element);
    return element;
  }

  function makeRow(label, parent) {
    const row = make("div", "recipe-row", parent);

    make("span", "recipe-row-label", row, label);

    const editable = make(
      "div",
      "recipe-value recipe-value--editable",
      row
    );

    const unit = make(
      "div",
      "recipe-unit-space",
      row
    );

    const applied = make(
      "div",
      "recipe-value recipe-value--applied",
      row
    );

    editable.setAttribute("aria-hidden", "true");
    unit.setAttribute("aria-hidden", "true");
    applied.setAttribute("aria-hidden", "true");
  }

  function fitHeader() {
    [
      [".recipe-title", 28],
      [".recipe-subtitle", 14]
    ].forEach(function (entry) {
      const element = document.querySelector(entry[0]);

      if (!element || element.hidden) return;

      const initialSize = entry[1];
      element.style.fontSize = initialSize + "px";

      if (
        element.clientWidth > 0 &&
        element.scrollWidth > element.clientWidth
      ) {
        element.style.fontSize =
          (
            initialSize *
            element.clientWidth /
            element.scrollWidth
          ) + "px";
      }
    });
  }

  /*
   * NOMBRE:
   * Título//Subtítulo
   *
   * Vacío: utiliza los textos predeterminados.
   * Sin "//": cambia solo el título.
   * "Título//": oculta el subtítulo.
   */
  function updateHeader(widget) {
    const title = document.querySelector(".recipe-title");
    const subtitle = document.querySelector(".recipe-subtitle");

    if (!title || !subtitle) return;

    const name =
      widget && typeof widget.name === "string"
        ? widget.name.trim()
        : "";

    const separator = name.indexOf("//");

    const titleText = separator < 0
      ? name
      : name.slice(0, separator).trim();

    const subtitleText = separator < 0
      ? DEFAULT_SUBTITLE
      : name.slice(separator + 2).trim();

    title.textContent = titleText || DEFAULT_TITLE;
    subtitle.textContent = subtitleText;
    subtitle.hidden = subtitleText === "";

    fitHeader();
  }

  function buildWidget() {
    const left = document.getElementById("recipe-left");
    const right = document.getElementById("recipe-right");

    if (!left || !right) return;

    left.replaceChildren();
    right.replaceChildren();

    LEFT_LABELS.forEach(function (label) {
      makeRow(label, left);
    });

    RIGHT_LABELS.forEach(function (label) {
      makeRow(label, right);
    });

    updateHeader(latestWidget || window.WIDGET || null);

    const heading = document.querySelector(".recipe-heading");

    if (
      heading &&
      typeof ResizeObserver !== "undefined"
    ) {
      if (headerObserver) {
        headerObserver.disconnect();
      }

      headerObserver = new ResizeObserver(fitHeader);
      headerObserver.observe(heading);
    } else {
      window.addEventListener("resize", fitHeader);
    }

    if (document.fonts && document.fonts.ready) {
      document.fonts.ready.then(fitHeader);
    }
  }

  /*
   * Widget exclusivamente visual.
   * No recibe tags ni ejecuta acciones sobre el PLC.
   * Solo actualiza el encabezado mediante NOMBRE.
   */
  window.onWidgetUpdate = function (widget) {
    latestWidget = widget;
    updateHeader(widget);
  };

  if (document.readyState === "loading") {
    document.addEventListener(
      "DOMContentLoaded",
      buildWidget,
      { once: true }
    );
  } else {
    buildWidget();
  }
})();
